#!/usr/bin/env python3
"""Generate src/online/player/actor_t5_root.c from a t5cap "dump" log.

The dump (Plutonium t5cap, scenario "dump") prints, for every T5 zombie and
hellhound move clip, the cumulative 2D root travel at 40 even steps of the
clip ("R <set>.<key> len=<s> d=0,a1,...,a40"), measured with getMoveDelta in
real T5.  C1 ships the same clips with different root tracks (some linear,
some raw and uneven), and T5's own tracks decide how fast its actors cover
ground frame by frame, so the server walks known clips on these profiles.

    python tools/t5_root_table.py obj/t5capture/t5_dump.txt [more dumps]

The key -> clip names come from the T5 scripts that fill the tables.
"""
import re
import sys
import os

T5 = r'D:\CoD\COD-GSC-Source\T5-STEAM-GSC'


def key_names():
    names = {}
    src = open(os.path.join(T5, 'maps', '_zombiemode.gsc'), encoding='latin-1').read()
    for k, v in re.findall(r'^\s*level\.scr_anim\["zombie"\]\["(\w+)"\]\s*=\s*%(\w+)\s*;', src, re.M):
        names['scr_anim.' + k] = v
    src = open(os.path.join(T5, 'animscripts', 'zombie_dog_init.gsc'), encoding='latin-1').read()
    for s, k, v in re.findall(r'anim\.dogAnims\["(\w+)"\]\.move\["(\w+)"\]\s*=\s*%(\w+)\s*;', src):
        names['dogmove.%s.%s' % (s, k)] = v
    return names


# C1 clips that stand in for a T5 clip C1 does not ship: c1 clip -> (T5 clip,
# C1 clip length in seconds).  The stand-in walks T5's track, time-scaled onto
# the C1 cycle, so it covers ground at the T5 clip's speed.
#   ai_zombie_run_v1 plays the run5 slot (T5's ai_zombie_run_v4, 94 u/s);
#   on its own track it ran 120 u/s (MEASURED, t5cap v2_run).
STANDINS = {
    'ai_zombie_run_v1': ('ai_zombie_run_v4', 57 / 30.0),
}


def main(paths):
    names = key_names()
    rows = {}
    for p in paths:
        for line in open(p, encoding='utf-8', errors='replace'):
            if not line.startswith('R '):
                continue
            parts = line.split()
            key = parts[1]
            length = float(parts[2].split('=')[1])
            cum = [float(x) for x in parts[3].split('=')[1].split(',')]
            clip = names.get(key)
            if not clip or len(cum) != 41 or length <= 0:
                continue
            rows[clip] = (length, cum, key)
    for c1, (t5, c1len) in STANDINS.items():
        if t5 in rows and c1 not in rows:
            length, cum, key = rows[t5]
            scale = c1len / length
            rows[c1] = (c1len, [c * scale for c in cum], key + ' (stand-in for %s)' % t5)
    out = os.path.join(os.path.dirname(__file__), '..', 'src', 'online', 'player', 'actor_t5_root.c')
    with open(out, 'w', newline='\n') as f:
        f.write('/* GENERATED by tools/t5_root_table.py from a t5cap "dump" of real\n'
                ' * T5 (Plutonium, getMoveDelta / getAnimLength).  Do not edit by hand.\n'
                ' *\n'
                ' * Cumulative 2D root travel of each T5 zombie / hellhound move clip at 40\n'
                ' * even steps.  actor_lifecycle.cpp walks an actor\'s path on these\n'
                ' * profiles instead of the C1 clip\'s own root track\n'
                ' * (docs/ZOMBIE_T5_MEASURED.md section 1). */\n'
                '#include <string.h>\n#include "actor_t5_root.h"\n\n'
                'static const t5_root_profile_t s_profiles[] = {\n')
        for clip in sorted(rows):
            length, cum, key = rows[clip]
            f.write('    { "%s", %.5ff, {%s} }, /* %s */\n' % (
                clip, length, ', '.join('%.2ff' % c for c in cum), key))
        f.write('};\n\n'
                'const t5_root_profile_t *T5RootProfile(const char *clip)\n{\n'
                '    if (!clip) return 0;\n'
                '    for (unsigned i = 0; i < sizeof(s_profiles) / sizeof(s_profiles[0]); ++i)\n'
                '        if (!strcmp(s_profiles[i].clip, clip)) return &s_profiles[i];\n'
                '    return 0;\n}\n\n'
                'float T5RootTravel(const t5_root_profile_t *p, float t)\n{\n'
                '    if (t <= 0.0f) return 0.0f;\n'
                '    if (t >= 1.0f) return p->cumulative[T5_ROOT_STEPS];\n'
                '    float x = t * T5_ROOT_STEPS;\n'
                '    unsigned i = (unsigned)x;\n'
                '    float f = x - (float)i;\n'
                '    return p->cumulative[i] + (p->cumulative[i + 1] - p->cumulative[i]) * f;\n}\n')
    print('wrote %d profiles to %s' % (len(rows), os.path.normpath(out)))
    missing = sorted(set(v for k, v in names.items()) - set(rows))
    if missing:
        print('no profile for: ' + ' '.join(missing))


if __name__ == '__main__':
    main(sys.argv[1:])
